<?php require '../../../config/bootstrap.php';$u=require_auth();$p=db();if($_SERVER['REQUEST_METHOD']==='GET'){[$page,$per,$off]=paginate();$s=$p->prepare('SELECT a.*,f.name farm_name FROM animals a JOIN farms f ON f.id=a.farm_id AND f.tenant_id=a.tenant_id WHERE a.tenant_id=? ORDER BY a.id DESC LIMIT ? OFFSET ?');$s->bindValue(1,$u['tenant_id'],PDO::PARAM_INT);$s->bindValue(2,$per,PDO::PARAM_INT);$s->bindValue(3,$off,PDO::PARAM_INT);$s->execute();json_response(['data'=>$s->fetchAll(),'page'=>$page,'per_page'=>$per]);}require_role($u,['owner','admin','manager','operator']);require_csrf();$d=request_json();foreach(['farm_id','tag_code','species'] as $k)if(empty($d[$k]))json_response(['error'=>"$k obrigatório"],422);$q=$p->prepare('SELECT id FROM farms WHERE id=? AND tenant_id=?');$q->execute([(int)$d['farm_id'],$u['tenant_id']]);if(!$q->fetch())json_response(['error'=>'Exploração inválida'],422);$s=$p->prepare('INSERT INTO animals(tenant_id,farm_id,tag_code,species,breed,sex,birth_date,notes) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$u['tenant_id'],(int)$d['farm_id'],$d['tag_code'],$d['species'],$d['breed']??null,$d['sex']??'unknown',$d['birth_date']??null,$d['notes']??null]);$id=(int)$p->lastInsertId();audit($u,'create','animal',$id,['tag_code'=>$d['tag_code']]);json_response(['id'=>$id],201);
